func rv64AssertCore3RefAsNonNullTrap(t *testing.T, in *Instance, name string, code coreruntime.TrapCode) {
	t.Helper()
	if got, err := in.Invoke(name); got != nil || err == nil {
		t.Fatal("pinned ref.as_non_null trap result", name, got, err)
	} else {
		var trap *coreruntime.TrapError
		if !errors.As(err, &trap) || trap.Code != code || len(trap.Frames) == 0 {
			t.Fatal("pinned ref.as_non_null trap", name, err)
		}
	}
}

func TestRV64Core3RefAsNonNullPinnedModule(t *testing.T) {
	source := rv64Core3RefAsNonNullSource()
	const sourceHash = "eae41a5ab39bf74adb9fc1e1fc0a40d31176598322ec57a3d4ab1a313a9c2c45"
	if got := fmt.Sprintf("%x", sha256.Sum256(source)); got != sourceHash {
		t.Fatalf("pinned ref_as_non_null.0.wasm hash = %s, want %s", got, sourceHash)
	}
	for _, artifact := range []bool{false, true} {
		t.Run(fmt.Sprintf("artifact%t", artifact), func(t *testing.T) {
			if os.Getenv("WAGO_RV64_TAIL_ARTIFACT_MODE") == "load" && !artifact {
				t.Skip("compiler-free artifact case only")
			}
			c := rv64NativeTailCompile(t, "core3-ref-as-non-null", source, artifact)
			wantFeatures := CoreFeatureBulkMemoryOperations | CoreFeatureReferenceTypes | CoreFeatureTypedFunctionReferences
			if c.requiredFeatures != wantFeatures || !c.nativeReferenceFunctionABI || !c.nativeReferenceCallABI || !c.nativeReferenceControlABI || !c.needsFuncRefDescs() {
				t.Fatal("pinned ref.as_non_null features and ABI witnesses", c.requiredFeatures)
			}
			if c.NumImports != 0 || len(c.Types) != 3 || len(c.Funcs) != 7 || c.tableCount() != 0 || len(c.Globals) != 0 || c.memoryCount() != 0 || c.HasStart || len(c.Exports) != 4 {
				t.Fatal("pinned ref.as_non_null closed module shape")
			}
			for name, index := range map[string]int{"nullable-null": 3, "nonnullable-f": 4, "nullable-f": 5, "unreachable": 6} {
				actual, ok := c.Exports[name]
				if !ok || actual != index || len(c.Funcs[index].Params) != 0 || !slices.Equal(c.Funcs[index].Results, []ValType{ValI32}) {
					t.Fatal("pinned ref.as_non_null numeric export", name, actual, ok)
				}
			}

			rt := NewRuntime(WithRuntimeConfig(rv64NativeTailConfig()))
			in := rv64NativeTokenInstantiate(t, rt, c, NewImports())
			if err := c.Close(); err != nil {
				t.Fatal(err)
			}
			rv64AssertCore3PassiveTarget(t, in, 2)
			if descriptor, ok := in.localFuncrefDescriptor(2); !ok || descriptor <= uint64(^uint32(0)) {
				t.Fatal("pinned ref.as_non_null full-width descriptor", descriptor, ok)
			}

			// The leading unreachable must win over the later null assertion. Both
			// traps and both successes remain reusable in their source order.
			rv64AssertCore3RefAsNonNullTrap(t, in, "unreachable", coreruntime.TrapUnreachable)
			rv64AssertCore3RefAsNonNullTrap(t, in, "nullable-null", coreruntime.TrapNullReference)
			for _, name := range []string{"nonnullable-f", "nullable-f"} {
				if got, err := in.Invoke(name); err != nil || !slices.Equal(got, []uint64{7}) {
					t.Fatal("pinned ref.as_non_null normalized i32 result", name, got, err)
				}
			}
			rv64AssertCore3RefAsNonNullTrap(t, in, "nullable-null", coreruntime.TrapNullReference)
			rv64AssertCore3RefAsNonNullTrap(t, in, "unreachable", coreruntime.TrapUnreachable)
			if got, err := in.Invoke("nonnullable-f"); err != nil || !slices.Equal(got, []uint64{7}) {
				t.Fatal("pinned ref.as_non_null reuse", got, err)
			}

			if err := in.Close(); err != nil {
				t.Fatal(err)
			}
			if err := rt.Close(); err != nil {
				t.Fatal(err)
			}
			if in.hasPhysicalResources() || c.codeCache.mem != nil || c.codeCache.refs != 0 {
				t.Fatal("pinned ref.as_non_null cleanup")
			}
		})
	}
}

func TestRV64Core3RefAsNonNullPinnedGates(t *testing.T) {
	if os.Getenv("WAGO_RV64_TAIL_ARTIFACT_MODE") == "load" {
		t.Skip("source and hostile artifact admission")
	}
	base := rv64NativeTailCompile(t, "core3-ref-as-non-null-gates", rv64Core3RefAsNonNullSource(), false)
	mutations := map[string]func(*Compiled){
		"missing-function-witness": func(c *Compiled) { c.nativeReferenceFunctionABI = false },
		"missing-control-witness":  func(c *Compiled) { c.nativeReferenceControlABI = false },
		"missing-context-trap":     func(c *Compiled) { c.nativeContextTrapABI = false },
		"missing-table-context":    func(c *Compiled) { c.nativeTableContextABI = false },
		"missing-table-reference":  func(c *Compiled) { c.nativeTableReferenceABI = false },
		"register-abi":             func(c *Compiled) { c.registerABIDisabled = false },
		"private-passive-target":   func(c *Compiled) { c.passiveElems[0].Values[0].FuncIndex = 0 },
	}
	for name, mutate := range mutations {
		t.Run(name, func(t *testing.T) {
			bad := rv64ReferenceStartCopy(base.executionView())
			mutate(bad)
			if err := railshotValidateCompiled(bad); !errors.Is(err, railshot.ErrUnsupported) {
				t.Fatal("hostile retained ref.as_non_null metadata admitted", err)
			}
			blob, err := marshalCompiled(bad)
			if err != nil {
				return
			}
			loaded, err := LoadTrustedArtifact(blob)
			if loaded != nil {
				loaded.Close()
			}
			if err == nil {
				t.Fatal("hostile serialized ref.as_non_null metadata admitted")
			}
		})
	}

	// The contract binds the recorded native ABI even where a narrower call
	// convention could execute this particular body.
	t.Run("internal-call-witness-binding", func(t *testing.T) {
		candidate := rv64ReferenceStartCopy(base.executionView())
		candidate.nativeReferenceCallABI = !candidate.nativeReferenceCallABI
		if err := candidate.validate(); err == nil {
			t.Fatal("edited internal call witness admitted")
		}
		rv64RequireRejectedArtifact(t, candidate)
		if !rv64ArtifactContractValid(base.executionView()) || base.executionView().validate() != nil {
			t.Fatal("edited call witness changed baseline")
		}
	})
}

func TestRV64Core3RefAsNonNullCompilerFreeGate(t *testing.T) {
	if os.Getenv("WAGO_RV64_TAIL_ARTIFACT_MODE") != "load" {
		t.Skip("actual compiler-free runtime only")
	}
	if c, err := Compile(nil, rv64Core3RefAsNonNullSource()); c != nil || err == nil || !strings.Contains(err.Error(), "source compilation is unavailable") {
		if c != nil {
			c.Close()
		}
		t.Fatal("compiler-free pinned ref.as_non_null used source compilation", err)
	}
}
